/**
 * CSP policy parity guard (CSP Phase 2C.2).
 *
 * FluentStellar sends exactly ONE CSP header in production —
 * `Content-Security-Policy` (real enforcement) — declared once in
 * src/security/csp.ts, reaching the browser through two independent
 * delivery surfaces that can never share a single HTTP response:
 *   - public/_headers (Cloudflare Static Assets — generated by
 *     scripts/security/generate-headers-file.mjs, never hand-edited)
 *   - workers/word-ssr/src/index.full.ts (the Worker's own response
 *     headers, via withDataVersionHeaders + the /records/* 404 guard)
 *
 * The enforcing policy carries only the directives already proven safe in
 * Phase 2B.1/2C.1 — deliberately NO script-src and NO default-src (see
 * src/security/csp.ts's file header for exactly why the default-src
 * omission matters: with script-src absent, default-src would otherwise
 * silently govern scripts too via CSP's own fallback rule).
 *
 * A second, full/strict policy (CSP_AUDIT_DIRECTIVES / the former
 * Content-Security-Policy-Report-Only header) remains DEFINED in
 * src/security/csp.ts — kept for a future CSP audit, but Phase 2C.2
 * deliberately stops either delivery surface from emitting it. This test
 * proves both halves of that:
 *   - the enforcing policy reaches both delivery surfaces correctly and
 *     never gains script-src/script-src-elem/script-src-attr/default-src
 *   - the audit policy's own integrity (hash, Cloudflare origin, no
 *     unsafe-inline/unsafe-eval) still holds, AND that neither delivery
 *     surface references it at all anymore, so it can't leak into
 *     production by accident while still living in source
 *
 * Run: node scripts/tests/security/test-csp-policy-parity.mjs
 * No build required — reads repo source files directly.
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { compileTsToCommonJs, ROOT_DIR } from "../../lib/compileTs.mjs";

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

function readFile(relPath) {
  return fs.readFileSync(path.join(ROOT_DIR, relPath), "utf8");
}

function mapsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const [key, values] of a) {
    const otherValues = b.get(key);
    if (!otherValues) return false;
    if (values.size !== otherValues.size) return false;
    for (const value of values) {
      if (!otherValues.has(value)) return false;
    }
  }
  return true;
}

function describeMap(map) {
  return [...map.entries()]
    .map(([directive, values]) => `${directive} ${[...values].sort().join(" ")}`)
    .sort()
    .join("; ");
}

// Extracts the header value from a single `_headers`-format rule block:
//   /*
//     Header-Name: value
// Anchored so "Content-Security-Policy:" never accidentally matches a
// "Content-Security-Policy-Report-Only:" line too (both start with the
// same prefix) — the (?!...) guard requires the header name to end
// exactly at the colon.
function extractHeadersFileValue(headersFileContent, headerName) {
  const re = new RegExp(`^\\s*${headerName}(?!-Report-Only):\\s*(.+)$`, "m");
  const match = headersFileContent.match(re);
  return match ? match[1].trim() : null;
}

const SCRIPT_GOVERNING_DIRECTIVES = ["script-src", "script-src-elem", "script-src-attr", "default-src"];

async function main() {
  const compiled = compileTsToCommonJs(".tmp-csp-policy-parity", [
    path.join(ROOT_DIR, "src", "security", "csp.ts"),
  ]);

  try {
    const csp = compiled.require("src/security/csp");
    const auditCanonicalMap = csp.parseCspHeaderValue(csp.buildCspAuditHeaderValue());
    const enforcingCanonicalMap = csp.parseCspHeaderValue(csp.buildCspEnforcingHeaderValue());

    const headersFile = readFile("public/_headers");
    const workerSource = readFile("workers/word-ssr/src/index.full.ts");

    console.log("\n[1] Header names are correct and distinct");
    test("csp.ts's CSP_AUDIT_HEADER_NAME is the Report-Only header-name string (used only if the audit policy is ever re-enabled)", () => {
      assert.equal(csp.CSP_AUDIT_HEADER_NAME, "Content-Security-Policy-Report-Only");
    });
    test("csp.ts's CSP_ENFORCING_HEADER_NAME is the real, enforcing header — the only one production sends", () => {
      assert.equal(csp.CSP_ENFORCING_HEADER_NAME, "Content-Security-Policy");
    });

    console.log("\n[2] CRITICAL: public/_headers declares ONLY the enforcing header — the audit/Report-Only header is retired from production");
    test("public/_headers declares Content-Security-Policy (enforcing)", () => {
      assert.ok(
        extractHeadersFileValue(headersFile, "Content-Security-Policy") !== null,
        "public/_headers is missing a Content-Security-Policy line",
      );
    });
    test("public/_headers does NOT declare Content-Security-Policy-Report-Only", () => {
      assert.equal(
        extractHeadersFileValue(headersFile, "Content-Security-Policy-Report-Only"),
        null,
        "public/_headers still emits the audit/Report-Only header — Phase 2C.2 retired it from production; " +
          "regenerate with `node scripts/security/generate-headers-file.mjs` after reverting any manual edit",
      );
    });
    test("public/_headers's rule block contains exactly one header line", () => {
      const ruleBlockMatch = headersFile.match(/\/\*\n([\s\S]*?)(?:\n\s*$|$)/);
      assert.ok(ruleBlockMatch, "could not locate the /* rule block in public/_headers");
      const headerLines = ruleBlockMatch[1].split("\n").filter((line) => line.trim().length > 0);
      assert.equal(headerLines.length, 1, `expected exactly 1 header line under /*, found ${headerLines.length}: ${headerLines.join(" | ")}`);
    });
    const headersFileEnforcingMap = csp.parseCspHeaderValue(
      extractHeadersFileValue(headersFile, "Content-Security-Policy") ?? "",
    );
    test("public/_headers's enforcing policy matches src/security/csp.ts's canonical enforcing policy", () => {
      assert.ok(
        mapsEqual(headersFileEnforcingMap, enforcingCanonicalMap),
        `public/_headers is stale — regenerate with \`node scripts/security/generate-headers-file.mjs\`.\n` +
          `  _headers: ${describeMap(headersFileEnforcingMap)}\n` +
          `  canonical: ${describeMap(enforcingCanonicalMap)}`,
      );
    });

    console.log("\n[3] CRITICAL: index.full.ts sends ONLY the enforcing header — no reference to the audit policy anywhere");
    test("index.full.ts imports the enforcing header-name and builder from src/security/csp", () => {
      assert.match(workerSource, /CSP_ENFORCING_HEADER_NAME/);
      assert.match(workerSource, /buildCspEnforcingHeaderValue/);
      assert.match(workerSource, /from\s*"\.\.\/\.\.\/\.\.\/src\/security\/csp"/);
    });
    test("index.full.ts does NOT import or reference the audit policy (CSP_AUDIT_HEADER_NAME / buildCspAuditHeaderValue) anywhere", () => {
      assert.ok(
        !/CSP_AUDIT_HEADER_NAME/.test(workerSource),
        "index.full.ts references CSP_AUDIT_HEADER_NAME — Phase 2C.2 retired the audit header from production; " +
          "the audit policy must stay defined only in src/security/csp.ts, never wired into a live response",
      );
      assert.ok(
        !/buildCspAuditHeaderValue/.test(workerSource),
        "index.full.ts calls buildCspAuditHeaderValue() — Phase 2C.2 retired the audit header from production",
      );
    });
    test("index.full.ts never hardcodes a CSP header name as a string literal itself", () => {
      // Both header names always flow through the imported constants — never
      // a locally hardcoded "Content-Security-Policy" / "...-Report-Only"
      // string, which would bypass csp.ts as the single source of truth.
      assert.ok(
        !/"Content-Security-Policy(-Report-Only)?"/.test(workerSource),
        "index.full.ts hardcodes a CSP header name string literal instead of importing the csp.ts constants",
      );
    });
    test("index.full.ts's withDataVersionHeaders attaches ONLY the enforcing header to every response it builds", () => {
      assert.match(workerSource, /\[CSP_ENFORCING_HEADER_NAME\]:\s*CSP_ENFORCING_HEADER_VALUE/);
    });
    test("index.full.ts's /records/* 404 guard (which bypasses withDataVersionHeaders) also carries ONLY the enforcing header", () => {
      const recordsGuardMatch = workerSource.match(
        /url\.pathname\.startsWith\("\/records\/"\)\)\s*\{\s*return new Response\("Not Found",\s*\{[\s\S]*?\}\);\s*\}/,
      );
      assert.ok(recordsGuardMatch, "could not locate the /records/* 404 guard — has it moved or been rewritten?");
      assert.match(recordsGuardMatch[0], /\[CSP_ENFORCING_HEADER_NAME\]:\s*CSP_ENFORCING_HEADER_VALUE/);
      assert.ok(
        !/CSP_AUDIT_HEADER_NAME/.test(recordsGuardMatch[0]),
        "the /records/* guard still attaches the audit/Report-Only header",
      );
    });
    test("buildCspEnforcingHeaderValue() is called exactly once (module scope) — no duplicated/reimplemented policy string", () => {
      const enforcingCalls = workerSource.match(/buildCspEnforcingHeaderValue\(\)/g) ?? [];
      assert.equal(enforcingCalls.length, 1);
    });

    console.log("\n[4] CRITICAL: the enforcing policy never gains script control, in the canonical definition or either delivery surface");
    for (const directive of SCRIPT_GOVERNING_DIRECTIVES) {
      test(`csp.ts's canonical enforcing policy has no "${directive}"`, () => {
        assert.equal(
          enforcingCanonicalMap.has(directive),
          false,
          `The enforcing policy must never contain "${directive}" — Cloudflare JavaScript Detections' inline ` +
            `bootstrap has no static hash and this project deliberately does not add 'unsafe-inline' or a nonce ` +
            `architecture for it yet (see src/security/csp.ts and the CSP Phase 2B.2 report). If this is a real, ` +
            `deliberate architecture change (e.g. a per-request nonce implementation), update this test ` +
            `intentionally — do not just delete the assertion.`,
        );
      });
      test(`public/_headers's enforcing line has no "${directive}"`, () => {
        assert.equal(headersFileEnforcingMap.has(directive), false);
      });
    }
    test("csp.ts's CSP_ENFORCING_DIRECTIVES is exactly the shared safe-directive list (identity, not just equal content)", () => {
      // Structural guard, not just an output check: the enforcing policy is
      // defined as literally the same array SAFE_NON_SCRIPT_DIRECTIVES the
      // audit policy spreads in — not a hand-copied second list that could
      // drift from it. Verified indirectly here: every enforcing directive
      // must also appear, byte-for-byte, in the audit policy (the reverse
      // isn't required — the audit policy additionally has
      // default-src/script-src).
      for (const [directive, sources] of enforcingCanonicalMap) {
        assert.ok(auditCanonicalMap.has(directive), `enforcing directive "${directive}" is missing from the audit policy entirely`);
        assert.deepEqual(
          [...sources].sort(),
          [...auditCanonicalMap.get(directive)].sort(),
          `enforcing and audit policies disagree on "${directive}"'s sources — they should be identical for every shared directive`,
        );
      }
    });

    console.log("\n[5] Audit-policy integrity (kept in source per Phase 2C.2, not deployed — still fully verified)");
    test("audit policy still has script-src", () => {
      assert.ok(auditCanonicalMap.has("script-src"), "script-src must remain in the audit policy definition");
    });
    test("audit script-src still carries the language-detection hash", () => {
      assert.ok(auditCanonicalMap.get("script-src").has(`'${csp.LANG_DETECT_SCRIPT_HASH}'`));
    });
    test("audit script-src still carries the Cloudflare Web Analytics beacon origin", () => {
      assert.ok(auditCanonicalMap.get("script-src").has(csp.CLOUDFLARE_INSIGHTS_SCRIPT_ORIGIN));
    });
    test("audit script-src contains exactly one sha256 hash — no unexplained hash constants", () => {
      const hashes = [...auditCanonicalMap.get("script-src")].filter((s) => s.startsWith("'sha256-"));
      assert.equal(hashes.length, 1);
      assert.equal(hashes[0], `'${csp.LANG_DETECT_SCRIPT_HASH}'`);
    });
    test("the two production-observed Cloudflare bot-management hashes are deliberately absent from audit script-src", () => {
      const hashes = [...auditCanonicalMap.get("script-src")].filter((s) => s.startsWith("'sha256-"));
      assert.ok(!hashes.includes("'sha256-+6sxCRtaYxlDFzRKgzgq0KslAhmiGkSgWp9ejhkPrHs='"));
      assert.ok(!hashes.includes("'sha256-fO0h6nSVSg6QGOtEkqzxNcpe9iJLgXxfCBJTJ4butWU='"));
    });
    test("audit script-src has no 'unsafe-inline'", () => {
      assert.ok(!auditCanonicalMap.get("script-src").has("'unsafe-inline'"));
    });
    test("audit script-src has no 'unsafe-eval'", () => {
      assert.ok(!auditCanonicalMap.get("script-src").has("'unsafe-eval'"));
    });
    test("audit policy still has default-src 'self'", () => {
      assert.deepEqual([...auditCanonicalMap.get("default-src")], ["'self'"]);
    });

    console.log("\n[6] No risky allowances beyond the deliberate, documented style-src exception (checked on both policies)");
    for (const [label, map] of [
      ["audit", auditCanonicalMap],
      ["enforcing", enforcingCanonicalMap],
    ]) {
      const allSources = [...map.values()].flatMap((set) => [...set]);
      test(`${label}: 'unsafe-inline' appears only in style-src`, () => {
        for (const [directive, sources] of map) {
          if (directive === "style-src") continue;
          assert.ok(!sources.has("'unsafe-inline'"), `'unsafe-inline' must not appear in ${label} ${directive}`);
        }
      });
      test(`${label}: no 'unsafe-eval' anywhere`, () => assert.ok(!allSources.includes("'unsafe-eval'")));
      test(`${label}: no bare wildcard '*' source`, () => assert.ok(!allSources.includes("*")));
      test(`${label}: no broad 'https:' scheme source`, () => assert.ok(!allSources.includes("https:")));
      test(`${label}: 'data:' appears only in img-src (Phase 2C.1 — flag-icons' build-inlined SVG data URIs)`, () => {
        for (const [directive, sources] of map) {
          if (directive === "img-src") continue;
          assert.ok(!sources.has("data:"), `'data:' must not appear in ${label} ${directive}`);
        }
      });
      test(`${label}: no 'blob:' source`, () => assert.ok(!allSources.includes("blob:")));
      test(`${label}: no broad subdomain wildcard (e.g. '*.example.com') anywhere`, () => {
        assert.ok(!allSources.some((source) => source.includes("*.")), `found a subdomain wildcard: ${allSources.filter((s) => s.includes("*."))}`);
      });
      test(`${label}: no bare https://cdn.jsdelivr.net (img-src must stay path-scoped)`, () => {
        assert.ok(!(map.get("img-src")?.has("https://cdn.jsdelivr.net") ?? false));
      });
      test(`${label}: no broad Cloudflare wildcard (e.g. *.cloudflare.com)`, () => {
        assert.ok(!allSources.some((source) => /cloudflare/i.test(source) && source.includes("*")));
      });
    }
    test("style-src carries 'unsafe-inline' in BOTH policies (Phase 2B.1/2C decision, enforced for real in production)", () => {
      assert.ok(csp.CSP_ALLOWS_UNSAFE_INLINE_STYLES, "expected this decision to be recorded in csp.ts");
      assert.ok(auditCanonicalMap.get("style-src").has("'unsafe-inline'"));
      assert.ok(enforcingCanonicalMap.get("style-src").has("'unsafe-inline'"));
    });

    console.log("\n[7] Expected required origins are present exactly where needed, in both policies where shared");
    test("connect-src (both policies) allows 'self' and the production Supabase origin, nothing else", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.deepEqual([...map.get("connect-src")].sort(), ["'self'", csp.SUPABASE_ORIGIN].sort());
      }
    });
    test("script-src (audit policy only) allows exactly the Cloudflare Web Analytics beacon origin, confirmed live in production", () => {
      assert.ok(auditCanonicalMap.get("script-src").has(csp.CLOUDFLARE_INSIGHTS_SCRIPT_ORIGIN));
      assert.equal(csp.CLOUDFLARE_INSIGHTS_SCRIPT_ORIGIN, "https://static.cloudflareinsights.com");
    });
    test("img-src (both policies) allows exactly the jsDelivr country-flags path prefix used by LanguageSelector.tsx, nothing broader", () => {
      const languageSelectorSource = readFile("src/app/components/LanguageSelector.tsx");
      assert.ok(
        languageSelectorSource.includes(csp.COUNTRY_FLAGS_IMG_SRC_PREFIX),
        "csp.ts's COUNTRY_FLAGS_IMG_SRC_PREFIX no longer matches the literal URL prefix LanguageSelector.tsx " +
          "actually uses — recheck the source and update the constant (and the pinned @main tag/path together).",
      );
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.ok(map.get("img-src").has(csp.COUNTRY_FLAGS_IMG_SRC_PREFIX));
      }
    });
    test("img-src (both policies) allows 'data:', for the flag-icons package's build-inlined SVG data URIs (Phase 2C.1)", () => {
      assert.ok(csp.IMG_SRC_ALLOWS_DATA_URIS, "expected this decision to be recorded in csp.ts");
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.ok(map.get("img-src").has("data:"));
      }
    });
    test("'data:' is not used as a broad fallback/default source — default-src (audit policy) has no 'data:', and the enforcing policy has no default-src at all to carry one", () => {
      assert.ok(!auditCanonicalMap.get("default-src").has("data:"));
      assert.equal(enforcingCanonicalMap.has("default-src"), false);
    });
    test("style-src (both policies) allows the Google Fonts stylesheet origin", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.ok(map.get("style-src").has("https://fonts.googleapis.com"));
      }
    });
    test("font-src (both policies) allows the Google Fonts file origin, not the stylesheet origin", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.ok(map.get("font-src").has("https://fonts.gstatic.com"));
        assert.ok(!map.get("font-src").has("https://fonts.googleapis.com"));
      }
    });
    test("script-src does NOT allow the Google Fonts origin (fonts are style/font-src concerns only)", () => {
      assert.ok(![...auditCanonicalMap.get("script-src")].some((s) => s.includes("fonts.g")));
    });
    test("frame-src and frame-ancestors are both 'none' in both policies", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.deepEqual([...map.get("frame-src")], ["'none'"]);
        assert.deepEqual([...map.get("frame-ancestors")], ["'none'"]);
      }
    });
    test("object-src is 'none' in both policies", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.deepEqual([...map.get("object-src")], ["'none'"]);
      }
    });
    test("base-uri and form-action are both 'self' in both policies", () => {
      for (const map of [auditCanonicalMap, enforcingCanonicalMap]) {
        assert.deepEqual([...map.get("base-uri")], ["'self'"]);
        assert.deepEqual([...map.get("form-action")], ["'self'"]);
      }
    });

    console.log(`\n─────────────────────────────────────────`);
    console.log(`  ${passed} passed, ${failed} failed`);
    console.log(`─────────────────────────────────────────\n`);

    if (failed > 0) {
      process.exitCode = 1;
    } else {
      console.log("CSP policy parity tests passed");
    }
  } finally {
    compiled.cleanup();
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
